insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '60591848-0736-5408-8aa6-19f86f483e73', id, null, 3, '3', 'Ser capaz de dar uma explicação sobre como estas cavernas se formaram, o que têm em comum e o que se pode esperar das mesmas em termos de características físicas, tais como tipo e tamanho das formações, efeitos da ação da água, presença e natureza de fósseis, presença e natureza de formas de vida, incluindo morcegos.', '2026-09-08 16:33:04', null from especialidades where codigo = 'AR-038' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
